#include <bits/stdc++.h>
using namespace std;

const int MAXNODES = 6010, INF = 0x3f3f3f3f;
int n, m, k, c, d, edge_idx, total_cost, a[MAXNODES], x[MAXNODES], y[MAXNODES];
int head[MAXNODES], parent[MAXNODES], dist[MAXNODES], inq[MAXNODES];
queue<int> q;
struct Edge { int to, capacity, cost, next; } graph[2000010];
int node_id(int t, int v) { return t * n + v; }

void addEdge(int u, int v, int capacity, int cost) {
    graph[edge_idx] = {v, capacity, cost, head[u]};
    head[u] = edge_idx++;
    graph[edge_idx] = {u, 0, -cost, head[v]};
    head[v] = edge_idx++;
}

bool spfa(int s, int t) {
    memset(dist, 0x3f, sizeof(dist));
    q.push(s);
    dist[s] = 0;
    while (!q.empty()) {
        int v = q.front(); q.pop(); inq[v] = 0;
        for (int i = head[v]; ~i; i = graph[i].next) {
            int u = graph[i].to;
            if (graph[i].capacity && dist[u] > dist[v] + graph[i].cost) {
                dist[u] = dist[v] + graph[i].cost;
                parent[u] = i;
                if (!inq[u]) { q.push(u); inq[u] = 1; }
            }
        }
    }
    return dist[t] < 1e9;
}

void processFlow(int s, int t) {
    for (int i = t; i != s; i = graph[parent[i] ^ 1].to) {
        graph[parent[i]].capacity--;
        graph[parent[i] ^ 1].capacity++;
    }
    total_cost += dist[t];
}

int main() {
    memset(head, -1, sizeof(head));
    scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);
    int S = 0, T = 6000;
    for (int i = 1; i <= k; i++) {
        scanf("%d", &a[i]);
        addEdge(S, node_id(0, a[i]), 1, 0);
    }
    for (int i = 1; i <= m; i++) {
        scanf("%d %d", &x[i], &y[i]);
    }
    for (int t = 0; t <= 100; t++) {
        for (int i = 2; i <= n; i++) {
            addEdge(node_id(t, i), node_id(t + 1, i), k, c);
        }
        addEdge(node_id(t, 1), T, k, 0);
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= min(k, 25); j++) {
                addEdge(node_id(t, x[i]), node_id(t + 1, y[i]), 1, c + (2 * j - 1) * d);
                addEdge(node_id(t, y[i]), node_id(t + 1, x[i]), 1, c + (2 * j - 1) * d);
            }
        }
    }
    while (spfa(S, T)) processFlow(S, T);
    printf("%d\n", total_cost);
    return 0;
}
